tw.local.sqlStatement[0] = new tw.object.SQLStatement();
tw.local.sqlStatement[0].sql = "SELECT * FROM " + tw.env.DBSchema + ".ODC_FCTRANSACTION WHERE ID = ? FOR UPDATE";
tw.local.sqlStatement[0].parameters = new tw.object.listOf.SQLParameter();

