 tw.local.sqlStatement[i].sql = "UPDATE " + tw.env.DBSchema + ".ODC_FCTRANSACTION SET AMOUNTLINKEDINBPM = ?, AMOUNTFORCURRENTREQ = ? , AMOUNTINREQCURRENCY = ? "+
							"WHERE REFERENCENO = ? AND CAST( POSTINGDATE AS DATE) = CAST ( ? AS DATE);"

