tw.local.sqlStatement = new tw.object.listOf.SQLStatement();

for(var i = 0 ; i<tw.local.transactions.listLength;i++){

	tw.local.sqlStatement[i] = new tw.object.SQLStatement();
	tw.local.sqlStatement[i].sql = "SELECT s.AMOUNTINCURRENTREQ, s.AMOUNTINREQCURRENCY FROM "+tw.env.DBSchema+".ODC_SELECTEDTRANSACTIONS s "+
							"JOIN "+tw.env.DBSchema+".ODC_FCTRANSACTION f ON s.TRANSACTIONID = f.ID "+
							"WHERE s.REQUESTID != ? AND s.ISDELETED <> 'Yes' AND f.REFERENCENO = ? AND CAST( f.POSTINGDATE AS DATE) = CAST ( ? AS DATE) "+
							"ORDER BY s.ID DESC FETCH FIRST 1 ROW ONLY;";			
	tw.local.sqlStatement[i].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(tw.local.requestID));
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(tw.local.changedTransactions[i].referenceNumber));
