ript","script":{"content":["tw.local.previousTransactions = [];
function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.sqlStatement = new tw.object.listOf.SQLStatement();


//get previous transaction list in case there is amend or recreate..note that "changeOpertaion" is a varaible that has requestID of previous request for each transaction

for(var i = 0 ; i<tw.local.transactions.listLength;i++){

	tw.local.sqlStatement[i] = new tw.object.SQLStatement();
	tw.local.sqlStatement[i].sql = "SELECT f.REFERENCENO , f.POSTINGDATE , s.AMOUNTINCURRENTREQ, s.AMOUNTINREQCURRENCY FROM "+tw.env.DBSchema+".ODC_SELECTEDTRANSACTIONS s "+
							"JOIN "+tw.env.DBSchema+".ODC_FCTRANSACTION f ON s.TRANSACTIONID = f.ID "+
							"WHERE s.REQUESTID = ? AND s.ISDELETED <> 'Yes' AND f.REFERENCENO = ? AND CAST( f.POSTINGDATE AS DATE) = CAST ( ? AS DATE) "+
							"ORDER BY s.ID DESC FETCH FIRST 1 ROW ONLY;";		
	tw.local.sqlStatement[i].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(parseInt(tw.local.transactions[i].changeOperation)));
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(tw.local.transactions[i].referenceNumber));
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(tw.local.transactions[i].postingDate));

}

//-----------------------------------------------
var ind = 0;
//map output
if(tw.local.sqlResult.listLength>0){
	for(var i =0;i<tw.local.sqlResult.listLength;i++){
		if(!!tw.local.sqlResult[i].rows[0]){
			if(!!tw.local.sqlResult[i].rows[0].data){
				tw.local.previousTransactions[ind] = new tw.object.FCTransactions();
				tw.local.previousTransactions[ind].referenceNumber = tw.local.sqlResult[i].rows[0].data[0];
				tw.local.previousTransactions[ind].postingDate = tw.local.sqlResult[i].rows[0].data[1];
				tw.local.previousTransactions[ind].existAmount = tw.local.sqlResult[i].rows[0].data[2];
				tw.local.previousTransactions[ind].amountAllocatedForCurrencyRequest = tw.local.sqlResult[i].rows[0].data[3];
				tw.local.previousTransactions[ind++].allocatedAmountInRequestCurrency = tw.local.sqlResult[i].rows[0].data[4];
			}
		}
	}

}

//----------------------------------------------------------
 function sameDate(dateStr1, dateStr2) {
 var d1 = new Date(dateStr1);
 var d2 = new Date(dateStr2);

 return d1.getDate() === d2.getDate() &&
 d1.getMonth() === d2.getMonth() &&
 d1.getFullYear() === d2.getFullYear();
 }
//compare lists

function compareLists(oldList, newList) {
 var added = [];
 var removed = [];
 var changed = [];

 // Check for added and changed items
 for (var i = 0; i < newList.length; i++) {
 var found = false;
 var isChanged = false;

 for (var j = 0; j < oldList.length; j++) {
 if (newList[i].referenceNo === oldList[j].referenceNo &&
 sameDate(newList[i].postingDate, oldList[j].postingDate)) {
 
 found = true;

 if (newList[i].existAmount !== oldList[j].existAmount) {
 isChanged = true;
 }

 break;
 }
 }

 if (!found) {
 added.insertIntoList(added[added.listLength], newList[i]);
 }

 if (isChanged) {
 changed.insertIntoList(changed[changed.listLength], newList[i]);
 }
 }

 // Check for removed items
 for (var i = 0; i < oldList.length; i++) {
 var found = false;

 for (var j = 0; j < newList.length; j++) {
 if (oldList[i].referenceNo === newList[j].referenceNo &&
 sameDate(oldList[i].postingDate, newList[j].postingDate)) {
 found = true;
 break;
 }
 }

 if (!found) {
 removed.insertIntoList(removed[removed.listLength], oldList[i]);
 }
 }

 return {
 added: added,
 removed: removed,
 changed: changed
 };
}

compareLists(tw.local.transactions , tw.local.previousTransactions);


//in case current/previous request is create 
if(tw.local.previousTransactions.listLength >0){
	for(var i = 0 ; i<tw.local.transactions.listLength;i++){

		tw.local.transactions[i].existAmount = tw.local.transactions[i].existAmount - tw.local.transactions[i].amountAllocatedForCurrencyRequest;
	}
}

//in case previous request is amend/recreate

var compareResult = compareLists(tw.local.previousTransactions , tw.local.transactions);

