//get previous transaction list in case there is amend or recreate..note that "changeOpertaion" is a varaible that has requestID of previous request for each transaction

for(var i = 0 ; i<tw.local.transactions.listLength;i++){

	tw.local.sqlStatement[i] = new tw.object.SQLStatement();
	tw.local.sqlStatement[i].sql = "SELECT f.REFERENCENO , f.POSTINGDATE , s.AMOUNTINCURRENTREQ,  s.AMOUNTINREQCURRENCY FROM "+tw.env.DBSchema+".ODC_SELECTEDTRANSACTIONS s "+
							"JOIN "+tw.env.DBSchema+".ODC_FCTRANSACTION f ON  s.TRANSACTIONID = f.ID "+
							"WHERE s.REQUESTID = ? AND s.ISDELETED <> 'Yes' AND f.REFERENCENO = ? AND CAST( f.POSTINGDATE AS DATE) = CAST ( ? AS DATE) "+
							"ORDER BY s.ID DESC FETCH FIRST 1 ROW ONLY;";		
	tw.local.sqlStatement[i].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(parseInt(tw.local.transactions[i].changeOperation)));
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(tw.local.transactions[i].referenceNumber));
	tw.local.sqlStatement[i].parameters.insertIntoList(tw.local.sqlStatement[i].parameters.listLength, addSQLParameter(tw.local.transactions[i].postingDate));

}

