				tw.local.previousTransactions[ind].postingDate = tw.local.sqlResult[i].rows[0].data[1];
				tw.local.previousTransactions[ind].existAmount =  tw.local.sqlResult[i].rows[0].data[2];
				tw.local.previousTransactions[ind].amountAllocatedForCurrencyRequest = tw.local.sqlResult[i].rows[0].data[3];
				tw.local.previousTransactions[ind++].allocatedAmountInRequestCurrency = tw.local.sqlResult[i].rows[0].data[4];
			}
		}
	}

}

//----------------------------------------------------------
  function sameDate(dateStr1, dateStr2) {
    var d1 = new Date(dateStr1);
    var d2 = new Date(dateStr2);

    return d1.getDate() === d2.getDate() &&
           d1.getMonth() === d2.getMonth() &&
           d1.getFullYear() === d2.getFullYear();
  }
//compare lists

function compareLists(oldList, newList) {
  var added = [];
  var removed = [];
  var changed = [];

  // Check for added and changed items
  for (var i = 0; i < newList.length; i++) {
    var found = false;
    var isChanged = false;

    for (var j = 0; j < oldList.length; j++) {
      if (newList[i].referenceNo === oldList[j].referenceNo &&
          sameDate(newList[i].postingDate, oldList[j].postingDate)) {
        
        found = true;

        if (newList[i].existAmount !== oldList[j].existAmount) {
          isChanged = true;
        }

        break;
      }
    }

    if (!found) {
      added.insertIntoList(added[added.listLength], newList[i]);
    }

    if (isChanged) {
      changed.insertIntoList(changed[changed.listLength], newList[i]);
    }
  }

  // Check for removed items
  for (var i = 0; i < oldList.length; i++) {
    var found = false;

    for (var j = 0; j < newList.length; j++) {
      if (oldList[i].referenceNo === newList[j].referenceNo &&
          sameDate(oldList[i].postingDate, newList[j].postingDate)) {
        found = true;
        break;
      }
    }

    if (!found) {
      removed.insertIntoList(removed[removed.listLength], oldList[i]);
    }
  }

  return {
    added: added,
    removed: removed,
    changed: changed
  };
}

compareLists(tw.local.transactions , tw.local.previousTransactions);


